      ],
      "quotes": [
        "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)). Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(5) Documentation of customary usage."
      ],
      "rationale": "The claim attempts to combine the core documentation requirement with several acceptable document types into a single claim. However, its explicit fields omit item (5) Documentation of customary usage from both the alternative list and summary, and completely fail to extract the exception for married names under 8 FAM 403.1-4(C). Furthermore, actor, action, and object are left blank, and the specific scope defining the three-way discrepancy is missing from the explicit scope fields.",
      "dimensions": {
        "summary": "error",
        "actor": "error",
        "support": "correct",
        "scope": "error",
        "links": "correct",
        "boundary": "error",
        "modality": "correct",
        "action": "error",
        "object": "error",
        "alternatives": "error",
        "thresholds": "not_applicable"
      }
    }
  ],
  "unit_judgments": [
    {
      "unit_id": "U0000",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "C0000 captures the requirement to document discrepancies with listed documents, but compresses the scope defining the discrepancies and omits the married-names exception.",
      "quotes": [
        "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section"
      ]
    },
    {
      "unit_id": "U0001",
      "claim_ids": [],
      "status": "missing",
      "rationale": "The exception for married names in 8 FAM 403.1-4(C) is present in the raw quote of C0000 but was omitted from the explicit meaning, summary, and boundaries, leaving it without a counterpart claim.",
      "quotes": [
        "(see an exception for married names in 8 FAM 403.1-4(C))"
      ]
    },
    {
      "unit_id": "U0002",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "Court orders or decrees are included as an alternative document type in C0000, but the governing regulatory citation to 22 CFR 51.25 is omitted from the explicit fields.",
      "quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ]
    },
    {
      "unit_id": "U0003",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "Name change orders are included in C0000's alternative list, but the explicit fields omit the governing regulatory basis (22 CFR 51.25).",
      "quotes": [
        "(a) Name change orders; or"
      ]
    },
    {
      "unit_id": "U0004",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "Divorce decrees are included in C0000's alternative list, but the governing regulatory basis (22 CFR 51.25) is omitted from the explicit fields.",
      "quotes": [
        "(b) Divorce decrees;"
      ]
    },
    {
      "unit_id": "U0005",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "Certificates of naturalization are included in C0000's alternative list, but without referencing the governing regulatory authority under 22 CFR 51.25.",
      "quotes": [
        "(2) Certificates of naturalization;"
      ]
    },
    {
      "unit_id": "U0006",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "Marriage certificates are included in C0000's alternative list, but without referencing the governing regulatory authority under 22 CFR 51.25.",
      "quotes": [
        "(3) Marriage certificates;"
      ]
    },
    {
      "unit_id": "U0007",
      "claim_ids": [
        "C0000"
      ],
      "status": "partial",
      "rationale": "Documentation demonstrating change of name by operation of state law is listed in C0000, but the governing authority under 22 CFR 51.25 is omitted.",
      "quotes": [
        "(4) Documentation demonstrating change of name by operation of state law; or"
      ]
    },
    {
      "unit_id": "U0008",
      "claim_ids": [],
      "status": "missing",
      "rationale": "Documentation of customary usage appears in the source and the quote of C0000, but was omitted from C0000's summary and explicit alternative list, leaving this acceptable alternative unrepresented.",
      "quotes": [
        "(5) Documentation of customary usage."
      ]
    }
  ]
}
